window.DGNL_DE_MON["l11"] = {"id": "l11", "ten": "Đề thi thử số 11", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Đọc hai câu sau<br><i>“...Con cò không nhát, sao gọi cò ma</i><br><i>Con cá không thờ, sao gọi cá linh...”</i><br>(Ca dao Việt Nam)<br>Hãy chọn phương án chứa biện pháp tu từ có trong đoạn trích", "choices": ["Điệp cấu trúc, điệp ngữ, chơi chữ", "Chơi chữ, điệp cấu trúc, nhân hoá", "So sánh, chơi chữ, điệp ngữ", "Câu hỏi tu từ, so sánh, nhân hoá"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Em hãy chọn câu đúng trong câu sau:", "choices": ["Với tập thơ Thanh Hiên thi tập đã khẳng định được tài năng của Nguyễn Du trong lĩnh vực sáng tác thơ chữ Hán.", "Cuộc sống bộn bề, tôi và gia đình dạo này chẳng có lấy một bữa cơm ngồi cùng nhau.", "Chiều sâu trong thông điệp tư tưởng của bài thơ sẽ khẳng định tầm vóc của một nhà thơ.", "Nhằm phổ biến những quy định pháp luật vừa được ban hành, thành lập Bản tin pháp luật ở thư viện."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Trải bao thỏ lặn, ác tà,</i><br><i>Ấy mồ vô chủ, ai mà viếng thăm!</i> (Truyện Kiều, Nguyễn Du)<br>Cụm từ “thỏ lặn, ác tà” có ý nghĩa chính xác nhất là gì trong đoạn thơ trên?", "choices": ["Cảnh tượng mặt trăng và mặt trời cùng hiện ra trên bầu trời.", "Hiện tượng thiên nhiên chuyển giao giữa ngày và đêm.", "Chỉ sự tuần hoàn của thời gian, ngày tháng trôi qua.", "Dấu hiệu của sự biến đổi trong vũ trụ và thời tiết."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu sai", "choices": ["Tôi chỉ nghe phong phanh rằng cô ấy sắp đi du học.", "Ai cũng đau xót khi nghe tin ngôi làng bị bão tàn phá.", "Tương lai của cô sinh viên trẻ thật xán lạn sau khi giành học bổng toàn phần.", "Buổi hoàng hôn bên bờ biển thật lãng mạn và yên bình."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng", "choices": ["Vì áp lực từ những ánh nhìn, cô đã buộc miệng nói điều không nên nói.", "Sự mẫn tiệt và nhanh nhạy của chú bé đã giúp cho dân làng thoát khỏi tai hoạ.", "Bà sinh ra trong một gia đình khuê các, được dạy dỗ theo nền nếp và am hiểu văn chương.", "Những hủ tục lạc hậu đã kiềm hãm sự phát triển của vùng nông thôn này."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Nói đến tinh thần &quot;_________&quot; tức là nói đến tinh thần nhập thế của đạo Phật, lấy ánh sáng của đức Phật để thắp sáng trần gian, “sống trong lòng thế tục, hòa ánh sáng của mình trong cuộc đời bụi bặm”, và biết cách biến sứ mệnh đạo Phật thành lý tưởng phụng sự cho đời, giải thoát khổ đau cho cá nhân và xã hội. Thời đại nhà Trần và đặc biệt vua Trần Nhân Tông (1258-1308) đã làm được điều này thành công rực rỡ, mở ra trang sử huy hoàng cho dân tộc.</i><br>Em hãy điền từ vào chỗ trống", "choices": ["Sát Thát", "Hào khí Đông A", "Hào quang đồng sàng", "Hoà quang đồng trần"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Những nhà bảo vệ môi trường đang tìm tương lai bền vững cho chốn “sơn kì thuỷ ___” trước áp lực từ lượng du khách ngày càng tăng lên.", "choices": ["tú", "tận", "mặc", "cốc"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>:</b> <i>“Đời tớ rất là buồn tẻ. Tớ đi săn gà, con người lại săn tớ. Gà thì con nào cũng giống con nào, còn người thì ai cũng giống ai. Vì thế tớ mới thấy hơi chán. Nhưng nếu cậu thuần hóa tớ, đời tớ sẽ như thể được mặt trời tỏa nắng. Tớ sẽ quen với tiếng một bước chân khác hẳn với những bước chân khác. Những bước khác khiến tớ cuống cuồng rúc xuống dưới đất. Tiếng bước chân của cậu sẽ gọi tớ ra khỏi hang, tựa như tiếng nhạc. Với cả hãy nhìn xem! Cậu thấy ở đằng kia không, cánh đồng lúa mì đó? Tớ chẳng ăn bánh mì. Lúa mì đối với tớ thật vô dụng. Cánh đồng lúa mì chả khiến cho tớ nhớ về điều gì hết. Và cái đó buồn kinh! Nhưng cậu lại có mái tóc màu vàng. Thế nên sẽ thật tuyệt vời khi mà cậu thuần hóa tớ! Lúa mì, vốn dĩ vàng óng, sẽ khiến tớ nhớ tới cậu. Và tớ sẽ yêu tiếng gió thổi trên đồng lúa mì.</i><br><i>Con cáo im bặt và nhìn hoàng tử bé rất lâu: &quot;Cậu làm ơn. hãy thuần hóa tớ!” nó nói.”</i><br>(<i>Hoàng tử bé</i>, Antoine de Saint-Exupéry (Trác Phong dịch)<br><b>Chi tiết “mái tóc màu vàng” của nhân vật hoàng tử bé có ý nghĩa là gì?</b>", "choices": ["Gợi lên vẻ đẹp ngây thơ, thuần khiết và quý tộc của hoàng tử bé - một hình ảnh lý tưởng hóa của trẻ thơ.", "Là chi tiết giúp cáo liên tưởng đến cánh đồng lúa mì, từ đó thể hiện ý nghĩa giá trị của mối quan hệ được xây dựng qua thuần hóa.", "Là biểu tượng cho ánh sáng, cho sự dẫn dắt và khai sáng tâm hồn những sinh vật cô đơn như cáo.", "Là nét đặc trưng thể chất được nhấn mạnh để thể hiện sự khác biệt giữa hoàng tử bé và thế giới loài người."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Non sông đã chết, sống thêm nhục</i><br><i>Hiền thánh còn đâu học cũng hoài!</i><br><i>Muốn vượt bể Đông theo cánh gió</i><br><i>Muôn trùng sóng bạc tiễn ra khơi.”</i><br>(<i>Lưu biệt khi xuất dương</i>, Phan Bội Châu)<br><b>Dòng nào sau đây KHÔNG thể hiện cảm xúc và tư tưởng của văn bản?</b>", "choices": ["Tâm trạng đau xót trước cảnh mất nước, nỗi trăn trở về vận mệnh dân tộc.", "Lòng quyết tâm ra đi tìm con đường cứu nước, vượt lên mọi gian khó.", "Tinh thần lạc quan yêu đời, say sưa thưởng ngoạn vẻ đẹp của thiên nhiên.", "Ý thức trách nhiệm của một người trí thức trước thời cuộc, khát vọng hành động vì dân tộc."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>:</b><i>“Nếu Đào Duy Từ đã từng băn khoăn về việc chọn “mình chúa”, mượn lời Khổng Minh thể hiện tâm sự mình trong “Ngọa long cương vân”, và cuối cùng, quyết định trốn vào Nam ra mắt chúa Nguyễn, nhanh chóng trở thành mưu thần, rồi thành quân sư, để lại một sự nghiệp cá nhân hấp dẫn nhiều nhà nho hậu thế, thì đi xa thêm một bước nữa trong tư tưởng, Nguyễn Hữu Chỉnh ký thác tâm sự mình vào hình ảnh Trương Lương qua bài phủ nổi tiếng “Trương Lưu hầu”. Tất cả các nhà nho đều thuộc lồng sự nghiệp Trương Lương “người dựng nên cơ đồ nhà Hán bồn trám năm”, và những người chí lớn tài cao xưa nay vẫn từng được so sánh với ông. Điểm đặc biệt là ở chỗ, Nguyễn Hữu Chỉnh không chỉ say mộ với một sự nghiệp lớn nói chung của Trương Lương, mà dành một sự chú ý cao dộ đối với các tính toán cụ thể, với cách lựa chọn của Trương Lương trong các tình huống phức tạp. Quan trọng nhất, là Nguyễn Hữu C</i>hỉnh phát hiện ra ở Trương Lương sự tự do trong việc lựa chọn hành động.”<br>(<i>Loại hình học tác giả văn học - Nhà nho tài tử và văn học Việt Nam</i>, Trần Ngọc Vương)<br><b>Đoạn trích trên sử dụng chủ yếu thao tác lập luận nào?</b>", "choices": ["Thao tác giải thích", "Thao tác chứng minh", "Thao tác so sánh", "Thao tác phân tích"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>Dòng nào sau đây nêu tên những tác phẩm cùng phong cách sáng tác của trường phái văn học hiện thực?</b>", "choices": ["Cơm thầy cơm cô (Vũ Trọng Phụng), Sợi tóc (Thạch Lam), Dì Hảo (Nam Cao)", "Trẻ con không ăn thịt chó (Nam Cao), Đời mưa gió (Nhất Linh), Trên đỉnh non Tản (Nguyễn Tuân)", "Người ngựa ngựa người (Nguyễn Công Hoan), Kỹ nghệ lấy Tây (Vũ Trọng Phụng), Giăng sáng (Nam Cao)", "Kép Tư Bền (Nguyễn Công Hoan), Sống mãi với thủ đô (Nguyễn Huy Tưởng), Đoạn tuyệt (Nhất Linh)"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Trước khi thực dân Pháp nổ phát súng đầu tiên xâm lược nước ta, mở đầu cho một trăm năm đô hộ.”</i><br><b>Câu trên là câu chưa hoàn chỉnh vì thiếu thành phần nào sau đây?</b>", "choices": ["Thiếu chủ ngữ.", "Thiếu vị ngữ.", "Thiếu trạng ngữ.", "Thiếu nòng cốt câu."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng", "choices": ["Với lực xoáy kinh hoàng, con đò chỉ còn là những mảnh tan tác.", "Đến bàn học, Thi vào phòng, ngồi xuống và bắt đầu làm bài tập về nhà.", "Từ ngày đảm nhận công tác quản lý đơn vị này, sự chăm chỉ của tập thể nhân viên mang đến cho tôi một cái nhìn thiện cảm.", "Lúc vồ vập, khi bẽn lẽn, cây đàn cứ như có một linh hồn riêng ngụ trong nó."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Trong các câu sau, câu nào mắc lỗi logic?", "choices": ["Nhờ sự giúp đỡ của bạn bè, tôi đã hoàn thành bài tập đúng thời hạn.", "Tuy trời mưa rất to nhưng chúng tôi vẫn quyết định hoãn chuyến đi.", "Vì quá lo lắng nên cô ấy đã quên mất những điều quan trọng cần nói.", "Dù gặp nhiều khó khăn, anh vẫn kiên trì theo đuổi mục tiêu của mình."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i><b>Cơm, </i></b><i>An sẽ nấu. </i><b><i>Quần áo</i></b><i>, Liên sẽ giặt. Quân chỉ cần quét và lau nhà thôi.</i><br>Thành phần được in đậm là thành phần gì?", "choices": ["Khởi ngữ", "Chủ ngữ", "Trạng ngữ", "Vị ngữ"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Nguyên người quanh quất đâu xa,<br>Họ Kim tên Trọng vốn nhà trâm anh.<br>[...]<br>Phong tư tài mạo tuyệt vời,<br>Vào trong phong nhã, ra ngoài hào hoa.<br>Chung quanh vẫn đất nước nhà<br>Với Vương Quan, trước vẫn là đồng thân.”<br>(Trích Truyện Kiều, Nguyễn Du)<br>Cụm từ “đồng thân” trong câu thơ có nghĩa là gì?", "choices": ["Người cùng dòng họ, huyết thống ruột thịt.", "Người quen biết, có quan hệ làm ăn.", "Bạn đồng môn, người cùng học một thầy.", "Người cùng quê hương, đồng làng xóm."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>ÔNG LÃO: – Thôi, chẳng qua là mày uất ức nên nói quẫn thế, chứ bố con mình xưa nay ăn ở hiền hậu mà còn cứ vận hạn mãi thế này, nếu lại làm những việc trái đạo thì còn giời nào chứng cho nữa.<br>ANH CẢ: – (…) Ăn ở hiền hậu mà cứ vận hạn mãi… Đến thế mà còn tin được Giời, Phật nữa à? (thất vọng). (…) Giời Phật, có để làm gì, hở? Có phải chỉ để làm bù nhìn mặc cho loài người chúng nó ăn thịt nhau, thằng nào xỏ lá, bất nhân, lắm ngón xoay tiền thì được vợ đẹp, con khôn, lên xe xuống ngựa; còn người hiền lành thật thà thì bị lợi dụng, bị đè nén, bị hắt hủi, kiếm chẳng đủ áo mặc cơm ăn có phải không? Có Giời, có Phật mà đến thế à? Không có Giời, Phật nào cả. Hoặc có Giời, có Phật nhưng Giời, Phật không đủ quyền phép thiêng liêng, không công minh, không đáng cho ai kính thờ!… Bây giờ ấy à? Chỉ có đồng tiền là Giời, là Phật, chỉ có đồng tiền là đáng kính thờ vì nó sai khiến được mọi người, ai ai cũng phải kính thờ nó mới sống được. Lương tâm à? Còn thua đồng tiền! Luật pháp à? Chưa bằng đồng tiền! Giời Phật à? Còn kém đồng tiền!…<br>Ông lão đang bị bệnh, lại đói, nghe con nói thế bỗng lả người đi như muốn ngã, nước dãi ở miệng chảy ra ròng ròng. Cả Thuận đỡ bố, nhăn nhó.<br>ÔNG LÃO: (không nói được nữa, chỉ kêu): Ôi giời ơi! Để tôi chết đi cho rảnh! Cho tôi chết đi!…<br>(Không một tiếng vang, Vũ Trọng Phụng)<br>Đoạn độc thoại của nhân vật Anh Cả thể hiện chủ yếu tư tưởng nào sau đây?", "choices": ["Sự vỡ mộng trước niềm tin về những rường cột đạo đức trong xã hội nơi đồng tiền chi phối các giá trị.", "Quan niệm thực dụng đề cao đồng tiền như thước đo tối thượng của giá trị sống trong xã hội hiện đại.", "Sự phủ nhận các giá trị tinh thần nhằm khẳng định quyền năng tuyệt đối của vật chất.", "Tâm trạng bi quan cực đoan dẫn đến cái nhìn lệch lạc về xã hội và con người."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Tôi nhốt con sáo vào lồng. Con sáo trở nên trái tính trái nết, nó không chịu học thêm những cầu mới, suốt ngày chỉ nhại đi nhại lại những câu tôi đã dạy. Ba tháng sau con sáo chết vi rách họng. Mẹ tôi chép miệng thở dài. Bố tôi bảo: “Thế cũng là cách tự giải phóng...”. Tôi thì tiếc ngẩn ngơ, vì từ nay tôi mất một người bạn. chị tôi năm ấy đang học lớp sáu đã ghi vào sổ tay: “Tuổi của một con sáo biết nói tiếng người là hai mươi mốt tháng năm ngày”. Tôi chôn con sáo ở gốc me ngoài cổng, đêm đêm tôi vẫn nghe tiếng nó cất lên cô đơn trong gió lạnh.</i><br>(Con sáo biết nói, Thái Sinh)<br>Đâu là thông điệp phù hợp với nội dung đoạn trích?", "choices": ["Việc áp đặt và tước đoạt tự do có thể làm tổn thương, thậm chí hủy hoại sự sống của một sinh thể.", "Con người cần kiên trì trong việc dạy dỗ để giúp các loài vật phát triển khả năng thích nghi với môi trường sống mới.", "Tình cảm gắn bó giữa con người và loài vật có thể giúp con người vượt qua những mất mát trong cuộc sống.", "Mỗi sinh thể đều có giới hạn sống tự nhiên, vì vậy con người cần chấp nhận quy luật sinh – tử một cách bình thản."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Với các nhà thơ _____, thế giới không thể chỉ được lĩnh hội bằng những quan năng tách bạch, nếu như thế người làm thơ sẽ tự hạn chế mình trong những điều có sẵn và nhìn thấy. Với họ, sự “phát minh” thế giới, mở rộng tầm nhìn của người nghệ sĩ là quan trọng. Đây chính là một trong những chìa khóa khuyến khích sự tự do sáng tạo cá nhân và không bị ràng buộc bởi bất kì quy tắc và giới hạn nào của thế giới hiện thực. “Thơ không giống với khoa học và đạo đức, nếu không thì sẽ suy thoái và chết đi. Nó không lấy chân thực làm đối tượng, nó chỉ lấy tự thân làm mục tiêu (…). Chân thực không có quan hệ gì với thơ. Ma lực làm nên một bài thơ, tất cả những ưu nhã và không thể chống cự đều có thể tước hết mọi quyền uy và sức mạnh của chân thực. Ngoài việc làm thơ thuần tuý chỉ vì khoan khoái, không có loại thơ nào vĩ đại không hổ thẹn với cái danh hiệu đó” (A.E.Poe).</i><br>(Lê Thị Ngà)<br>Chọn từ thích hợp nhất điền vào chỗ trống.", "choices": ["tượng trưng", "siêu thực", "hiện đại", "trung đại"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Nhà thơ Đặng Thân trong một bài viết có tên Mai Văn Phấn và công nghệ cách tân thơ đã từng nhận xét: &quot;Thơ Mai Văn Phấn chan chứa cả trời ______”. Không chỉ tìm về với miền _____ của con người, thơ Mai Văn Phấn với ảnh hưởng của khuynh hướng siêu thực còn đề cao cái ngẫu hứng, chú trọng việc ghi chép những cái xuất hiện lướt qua trong đầu không qua sự kiểm soát của lí trí.<br>Một từ có thể điền vào hai chỗ trống là gì?", "choices": ["vô thức", "kí ức", "cảm xúc", "đau thương"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<i>Hòa Bình là tỉnh có nhiều dân tộc sinh sống, trong đó đông nhất là dân tộc Mường, tiếp đó là dân tộc Kinh, Thái, Dao, Tày, Mông và các dân tộc khác. Mỗi dân tộc đều có ngôn ngữ riêng bên cạnh tiếng Việt là ngôn ngữ quốc gia. Nhắc đến Hòa Bình là nhắc đến dân tộc Mường với đặc điểm vừa tập trung về dân số vừa đậm đà về đời sống văn hóa ngôn ngữ Mường. Là 1 trong 6 dân tộc thiểu số có số dân trên 1 triệu người, nhưng dân tộc Mường chưa có bộ chữ chính thức, trong khi 5 dân tộc: Tày, Thái, Khmer, Mông, Nùng đều có chữ viết. Năm 2016, với sự lãnh đạo, chỉ đạo sát sao của Tỉnh ủy, UBND tỉnh, bộ chữ viết dân tộc Mường tỉnh Hòa Bình đã được xây dựng và chính thức đưa vào sử dụng. Đó là một dấu mốc quan trọng của dân tộc Mường, gắn với 130 năm xây dựng và phát triển của tỉnh.</i><br><i>Tiếng Mường là tiếng mẹ đẻ của dân tộc Mường. Cho đến nay, tuyệt đại đa số các ý kiến đều thống nhất cho rằng, người Mường và người Kinh có chung nguồn gốc với giả thuyết có người Việt - Mường cổ trước đó</i><b><i>. Xét về mặt ngữ hệ (nguồn gốc), tiếng Mường và tiếng Việt đều có một nguồn gốc chung là thuộc nhóm Việt Mường. Nhóm này, ngoài tiếng Việt, tiếng Mường còn có tiếng Thổ, tiếng Chứt và các tiếng khác như tiếng Cuối, tiếng Poọng, tiếng Arem, tiếng Mã Liềng. Xét từ góc độ loại hình học, tiếng Mường có cùng loại hình với tiếng Việt, thuộc loại hình ngôn ngữ đơn lập với những đặc điểm: Từ không biến đổi hình thái; quan hệ ngữ pháp và ý nghĩa ngữ pháp được biểu thị chủ yếu bằng hư từ, trật tự từ và ngữ điệu; từ có tính phân tiết, các từ đơn tiết làm thành hạt nhân cơ bản của từ vựng; ranh giới các âm tiết thường trùng với ranh giới các hình vị. Xét từ góc độ chức năng, tiếng Mường là ngôn ngữ dùng để giao tiếp trong nội bộ dân tộc Mường, bên cạnh tiếng Việt với tư cách là ngôn ngữ quốc gia.</i></b>", "cauHoi": [{"question": "Phần in đậm trình bày thông tin theo cấu trúc nào?", "choices": ["Thông tin chính – thông tin chi tiết", "Phân loại đối tượng", "Trật tự thời gian", "Trật tự không gian"], "correctIndex": 2, "explain": ""}, {"question": "Đặc điểm nào sau đây <b>KHÔNG</b> đúng với loại hình ngôn ngữ của tiếng Mường theo đoạn trích?", "choices": ["Từ không biến đổi hình thái.", "Quan hệ ngữ pháp thể hiện qua trật tự từ và hư từ.", "Từ chủ yếu là đa tiết, cấu tạo phức tạp.", "Các âm tiết thường trùng với ranh giới hình vị."], "correctIndex": 2, "explain": ""}, {"question": "Đoạn trích gợi ra nhận thức nào sau đây về vai trò của ngôn ngữ dân tộc thiểu số?", "choices": ["Ngôn ngữ dân tộc thiểu số chỉ có giá trị giao tiếp nội bộ.", "Ngôn ngữ dân tộc thiểu số cần được thay thế dần bằng tiếng Việt để thống nhất quốc gia.", "Việc bảo tồn và phát triển ngôn ngữ dân tộc thiểu số góp phần giữ gìn bản sắc văn hóa và đa dạng ngôn ngữ.", "Ngôn ngữ dân tộc thiểu số không có mối liên hệ nào với tiếng Việt."], "correctIndex": 2, "explain": ""}, {"question": "Nhan đề nào sau đây phù hợp nhất với nội dung văn bản?", "choices": ["Tiếng Mường và vai trò trong đời sống văn hóa Hòa Bình", "Đặc điểm và vị trí của tiếng Mường trong hệ thống ngôn ngữ Việt Nam", "Quá trình hình thành và phát triển chữ viết dân tộc Mường", "Sự đa dạng dân tộc và ngôn ngữ ở tỉnh Hòa Bình"], "correctIndex": 1, "explain": ""}, {"question": "Bên cạnh thuyết minh, phương thức biểu đạt nào trong các phương thức sau đây xuất hiện nổi bật nhất trong văn bản?", "choices": ["Tự sự", "Miêu tả", "Biểu cảm", "Nghị luận"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<i>“Nghĩ thương lời chị dặn dò</i><br><i>Mười lăm năm đắm con đò xuân xanh</i><br><i>Chị yêu lệ chảy đã đành</i><br><i>Chớ em nước mắt đâu dành chàng Kim</i><br><i>Ơ kìa sao chị ngồi im</i><br><i>Máu còn biết chảy về tim để hồng</i><br><i>Lấy người yêu chị làm chồng</i><br><i>Đời em thể thắt một vòng oan khiên</i><br><i>Sụt sùi ướt cỏ Đạm Tiên</i><br><i>Chị thương kẻ khuất, đừng quên người còn</i><br><i>Mấp mô số phận vuông tròn</i><br><i>Đất không thể nhốt linh hồn đòi yêu!</i><br><i>Là em nghĩ vậy thôi, Kiều</i><br><i>Sánh sao đời chị ba chiều bão giông</i><br><i>Con đò đời chị về không</i><br><i>Chở theo tiếng khóc đáy sông Tiền Đường</i><br><i>Chị nhiều hờn giận, yêu thương</i><br><i>Vầng trăng còn lấm mùi hương hẹn hò</i><br><i>Em chưa được thế bao giờ</i><br><i>Tiết trinh thương chị đánh lừa trái tim!</i><br><i>Em thành vợ của chàng Kim</i><br><i>Ngồi ru giọt máu tượng hình chị trao</i><br><i>Giấu đầy đêm nỗi khát khao</i><br><i>Kiều ơi, em đợi kiếp nào để yêu!”</i><br>(Tâm sự nàng Thuý Vân, Trương Nam Hương)", "cauHoi": [{"question": "Dạng thức chủ thể trữ tình của đoạn thơ trên là gì?", "choices": ["Chủ thể trữ tình trực tiếp", "Chủ thể trữ tình ẩn", "Sự kết hợp giữa chủ thể trữ tình trực tiếp và chủ thể trữ tình nhập vai", "Chủ thể trữ tình nhập vai"], "correctIndex": 3, "explain": ""}, {"question": "Câu thơ “Tiết trinh thương chị đánh lừa trái tim!” thể hiện rõ nhất nghịch lí nào?", "choices": ["Giữa đạo đức truyền thống và khát vọng cá nhân không thể dung hòa.", "Giữa tình chị em và nghĩa vợ chồng trong xã hội phong kiến.", "Giữa cái đẹp hình thức và đời sống nội tâm con người.", "Giữa lí trí và cảm xúc trong tình yêu đôi lứa."], "correctIndex": 0, "explain": ""}, {"question": "Đoạn thơ đã đối thoại với Truyện Kiều ở điểm nào?", "choices": ["Phản đối cách khắc hoạ nhân vật Thuý Vân của Nguyễn Du.", "Bổ sung chi tiết mới nhằm làm phong phú thêm cốt truyện gốc.", "Tái diễn giải số phận nhân vật từ một điểm nhìn khác.", "Giữ nguyên cách nhìn truyền thống nhưng thay đổi hình thức biểu đạt."], "correctIndex": 2, "explain": ""}, {"question": "Cụm từ “mười lăm năm đắm con đò xuân xanh” trong khổ thơ đầu nhằm ám chỉ điều gì về cuộc đời Thúy Kiều?", "choices": ["Quãng thời gian Kiều sống hạnh phúc, êm đềm bên gia đình và Kim Trọng.", "Quãng đời mười lăm năm lưu lạc, truân chuyên và đánh mất tuổi thanh xuân của Kiều.", "Sự tiếc nuối của Thúy Vân về việc không được cùng chị đi du ngoạn.", "Hành trình đi tìm hạnh phúc đích thực của người phụ nữ trong xã hội cũ."], "correctIndex": 1, "explain": ""}, {"question": "Đâu <b>KHÔNG</b> phải là lý do khiến nhân vật Thúy Vân cảm thấy đau xót và bi kịch trong cuộc hôn nhân với Kim Trọng theo văn bản trên?", "choices": ["Vì Thúy Vân nhận ra mình chỉ là “người đóng thế” cho chị, sống trong một tình yêu mà “mùi hương hẹn hò” vốn thuộc về người khác.", "Vì Thúy Vân cảm thấy tội lỗi khi đã chiếm đoạt hạnh phúc và tình yêu đích thực của Thúy Kiều.", "Vì Thúy Vân xót xa khi thấy chị mình phải lưu lạc mười lăm năm, còn mình thì “đợi kiếp nào để yêu” một tình yêu thực sự.", "Vì Thúy Vân nhận ra đời Kiều dù đẫm lệ nhưng ít ra chị đã được khóc cho người chị yêu."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}], "anh": [{"noiDungChung": null, "cauHoi": [{"question": "<i class=\"huong-dan-cau\">Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i><br>There was no one nearby who might see him trying to break ___ the house.", "choices": ["into", "up", "off", "out"], "correctIndex": 0, "explain": "<b>Câu 31. Chọn đáp án A.</b> Giải thích: Cụm động từ <b>&quot;break into&quot;</b> có nghĩa là đột nhập vào (nhà, văn phòng...) trái phép."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "He couldn&#x27;t make a sandwich because he ____ to buy bread.", "choices": ["was forgetting", "has forgotten", "had forgotten", "is forgetting"], "correctIndex": 2, "explain": "<b>Chọn đáp án C.</b> Giải thích: Sử dụng thì <b>Quá khứ hoàn thành</b> (had forgotten) để diễn tả một hành động xảy ra và hoàn thành trước một hành động khác trong quá khứ (couldn&#x27;t make)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "It was ___ weather for the outdoor event, so it got canceled.", "choices": ["the best", "the worst", "better than", "worse than"], "correctIndex": 1, "explain": "<b>Chọn đáp án B.</b> Giải thích: Dựa vào ngữ cảnh sự kiện bị hủy (canceled), ta cần dùng so sánh nhất <b>&quot;the worst&quot;</b> (tệ nhất) để chỉ điều kiện thời tiết."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Watersport enthusiasts should consider ____ a wetsuit as well as a life jacket.", "choices": ["hire", "to hire", "to hiring", "hiring"], "correctIndex": 3, "explain": "<b>Chọn đáp án D. </b>Giải thích: Cấu trúc động từ &quot;consider + V-ing&quot; (xem xét, cân nhắc làm việc gì)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Doctors work an average of 90 hours a week, while ___ are on call for up to 120 hours.", "choices": ["a few", "a little", "much", "an amount of"], "correctIndex": 0, "explain": "<b>Chọn đáp án A.</b> Giải thích: <b>&quot;A few&quot;</b> đi với danh từ đếm được số nhiều (doctors) mang nghĩa là &quot;một vài&quot;. Các phương án còn lại đi với danh từ không đếm được hoặc chỉ số lượng tổng thể."}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 36-40: Each of the following sentences has one error (A, B, C, or D). Find it and blacken your choice on your answer sheet.</i></b>", "cauHoi": [{"question": "I can think <u>of</u> half <u>the</u> dozen <u>friends</u> with backgrounds like <u>his</u>.", "choices": ["of", "the", "friend", "his."], "correctIndex": 1, "explain": "<b>Chọn đáp án B.</b> Giải thích: Cụm từ đúng là <b>&quot;half a dozen&quot;</b> (nửa tá/sáu cái). Không dùng mạo từ &quot;the&quot; trong trường hợp này."}, {"question": "A variety of delicious <u>dishes</u> <u>is</u> being served at the event, <u>ranging</u> from vegetarian options <u>to</u> hearty meat dishes.", "choices": ["dishes", "is", "ranging", "to"], "correctIndex": 1, "explain": "<b>Chọn đáp án B.</b> Giải thích: Chủ ngữ là <b>&quot;A variety of + danh từ số nhiều&quot;</b> thì động từ phải chia ở số nhiều. Sửa &quot;is&quot; thành <b>&quot;are&quot;</b>."}, {"question": "He was a man for <u>who</u> the demolition of <u>a</u> church was as painful <u>as</u> the felling of a friend.", "choices": ["who", "the", "a", "as"], "correctIndex": 0, "explain": "<b>Chọn đáp án A.</b> Giải thích: Sau giới từ &quot;for&quot;, ta phải dùng đại từ quan hệ <b>&quot;whom&quot;</b> thay vì &quot;who&quot; để chỉ người."}, {"question": "<u>He</u> blasted <u>the</u> measure for <u>their</u> lack <u>of</u> regulations and shortsighted approach.", "choices": ["He", "the", "their", "of"], "correctIndex": 2, "explain": "<b>Chọn đáp án C.</b> Giải thích: Tính từ sở hữu phải tương ứng với danh từ số ít &quot;the measure&quot;. Sửa &quot;their&quot; thành <b>&quot;its&quot;</b>."}, {"question": "My <u>parents</u> garden <u>is</u> beautiful <u>because</u> they grow <u>a</u> lot of flowers.", "choices": ["parents", "is", "because", "a."], "correctIndex": 0, "explain": "<b>Chọn đáp án A.</b> Giải thích: Lỗi sở hữu cách. Cần thêm dấu phẩy để chỉ khu vườn của bố mẹ: <b>&quot;parents&#x27;&quot;</b> hoặc <b>&quot;parent&#x27;s&quot;</b>."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: </b>Which of the following best restates each of the given sentences?", "cauHoi": [{"question": "“Finish your homework before you go out,” said Mom.", "choices": ["Mom invited me to finish my homework before I went out.", "Mom insisted on finishing my homework before I went out.", "Mom asked me if I finished my homework before I went out.", "Mom told me to finish my homework before I went out."], "correctIndex": 3, "explain": "<b>Chọn đáp án D. </b>Giải thích: Câu mệnh lệnh &quot;Finish...&quot; chuyển sang gián tiếp thường dùng cấu trúc &quot;tell someone to do something&quot;."}, {"question": "The flight was delayed because it snowed heavily.", "choices": ["The flight would be delayed unless it snowed heavily.", "If it hadn’t snowed heavily, the flight wouldn’t have been delayed.", "If it snows heavily, the flight will not be delayed.", "If it snowed heavily, the flight would not be delayed."], "correctIndex": 1, "explain": "<b>Chọn đáp án B.</b> Giải thích: Sử dụng câu điều kiện loại 3 để diễn tả một giả thiết trái ngược với thực tế đã xảy ra trong quá khứ (Vì tuyết rơi nên chuyến bay bị hoãn)."}, {"question": "No one in the class reads faster than Lisa.", "choices": ["Lisa doesn’t read faster than anyone in the class.", "Lisa reads as fast as everyone in the class.", "Everyone reads faster than Lisa in the class.", "Lisa is the fastest reader in the class."], "correctIndex": 3, "explain": "<b>Chọn đáp án D. Giải thích: So sánh hơn nhất (fastest reader) tương đương với cấu trúc &quot;Không ai... hơn&quot; (No one... faster than).</b>"}, {"question": "It is advisable for students to review their notes before the test.", "choices": ["Students have to review their notes before the test.", "Students must review their notes before the test.", "Students should review their notes before the test.", "Students should have reviewed their notes before the test."], "correctIndex": 2, "explain": "<b>Chọn đáp án C.</b> Giải thích: <b>&quot;It is advisable&quot;</b> (nên làm gì) tương đương với động từ khuyết thiếu <b>&quot;should&quot;</b>."}, {"question": "The streets are emptier now, possibly because of the late hour.", "choices": ["The decline in the number of people on the streets is unlikely due to the late hour.", "It is possible that the late hour will not affect the number of people on the streets.", "The decline in the number of people on the streets is certainly due to the late hour.", "The late hour may be the reason for the emptier streets."], "correctIndex": 3, "explain": "<b>Chọn đáp án D. Giải thích: &quot;Possibly&quot; (có khả năng) tương đương với động từ khuyết thiếu &quot;may&quot;.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question.</i></b><br><b>1.</b> Technology is now a big part of our daily lives, making many tasks easier and faster. Smartphones, which were once a luxury, are now <b>essential</b>. They help us stay connected, work, and find information. With just a tap, we can search for anything, talk to friends on social media, or shop online. These devices are useful not only for socializing but also for organizing our day.<br><b>2. </b>Smart home systems have changed how we live. We can now control lights, thermostats, and even locks from our phones, making life more convenient and secure. These smart systems also save energy and lower bills by adjusting to how we use <b>them</b>. In the kitchen, smart appliances make cooking easier and can even suggest recipes based on what food we have.<br><b>3.</b> Technology has also made it easier to take care of our health. Fitness trackers help us stay active<br>and monitor how much we move. They also track our sleep and give tips to improve rest. Telemedicine allows us to talk to doctors through video calls, which is very helpful for people who<br>live far from clinics or find it hard to travel.<br><b>4. </b>Transportation has improved too. GPS helps us find the best routes, and apps like ride-sharing<br>make traveling easier. Electric and self-driving cars are becoming more popular, making transport safer and better for the environment. Even public transport is better, with apps giving real-time updates about buses and trains.<br><b><i>Choose an option (A, B, C, or D) that best answers each question.</i></b>", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["The role of technology in transforming daily life", "The negative impacts of smartphones", "How home appliances are becoming smarter", "The dangers of working remotely"], "correctIndex": 0, "explain": "<b>Chọn đáp án A.</b> Giải thích: Toàn bộ bài viết nói về việc công nghệ thay đổi các khía cạnh khác nhau trong đời sống hàng ngày (nhà ở, y tế, giao thông)."}, {"question": "The closest meaning to &quot;<b>essential</b>&quot; in paragraph 1 is:", "choices": ["Unnecessary", "Important", "Useless", "Costly."], "correctIndex": 1, "explain": "<b>Chọn đáp án B.</b> Giải thích: <b>&quot;Essential&quot;</b> có nghĩa là thiết yếu, quan trọng, đồng nghĩa với <b>&quot;Important&quot;</b>."}, {"question": "What does the word &quot;<b>them</b>&quot; refer to in paragraph 2?", "choices": ["Smart home systems", "Food recipes", "People who use technology", "Ubility bills"], "correctIndex": 0, "explain": "<b>Chọn đáp án A.</b><br>Giải thích: Từ &quot;them&quot; ở đây thay thế cho &quot;these smart systems&quot; (các hệ thống thông minh) đã nhắc đến ở câu trước."}, {"question": "What is stated in paragraph 2 about smart home systems?", "choices": ["They make it harder to control energy use.", "They are not yet widely available.", "They are only used to control lighting and locks.", "They save energy by adjusting usage based on habits."], "correctIndex": 3, "explain": "<b>Chọn đáp án D. Giải thích: Đoạn 2 ghi rõ: &quot;...save energy and lower bills by adjusting to how we use them&quot; (tiết kiệm năng lượng bằng cách điều chỉnh theo cách sử dụng).</b>"}, {"question": "In paragraph 3, which of the following is NOT mentioned as a benefit of technology?", "choices": ["Fitness trackers help us stay active.", "Telemedicine allows people to consult doctors remotely.", "Fitness trackers suggest recipes for cooking.", "Technology helps monitor sleep patterns."], "correctIndex": 2, "explain": "<b>Chọn đáp án C.</b> Giải thích: Việc gợi ý công thức nấu ăn được nhắc đến ở đoạn 2 (nhà bếp), không phải lợi ích của thiết bị theo dõi sức khỏe ở đoạn 3."}, {"question": "What can be inferred about the role of technology in health care in paragraph 3?", "choices": ["Telemedicine is only used for emergencies.", "Fitness trackers are only useful for athletes.", "Wearable devices are not useful for sleep improvement.", "Technology is making health care more accessible to people in remote areas."], "correctIndex": 3, "explain": "<b>Chọn đáp án D. Giải thích: Telemedicine (khám bệnh từ xa) giúp ích cho những người sống xa phòng khám hoặc khó khăn khi di chuyển (vùng sâu vùng xa).</b>"}, {"question": "What is stated about transportation in paragraph 4?", "choices": ["Ride-sharing apps have made transportation more expensive.", "Electric cars are less popular than traditional vehicles.", "Public transport has been improved with real-time updates.", "GPS systems are not reliable."], "correctIndex": 2, "explain": "<b>Chọn đáp án C.</b> Giải thích: Đoạn 4 nêu: &quot;...public transport is better, with apps giving real-time updates&quot; (phương tiện công cộng tốt hơn nhờ các ứng dụng cập nhật thời gian thực)."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: <b>Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.</b><br><b>1.</b> Karaoke has become more than a pastime in Vietnam, it’s a deeply rooted part of social life. From birthday parties to wedding celebrations, this activity unites friends, families, and even strangers in an experience that is as much about connection as it is about music. However, the fun comes with <b>downsides</b>: noise disputes and fierce competition.<br><b>2. </b>Karaoke as we know it today originated in Japan, but its journey to Vietnam was swift and transformative. The 1990s saw the rapid rise of karaoke bars in major cities like Hanoi and Ho Chi Minh City, particularly in the more affluent neighborhoods. Initially, karaoke was a luxury reserved for the wealthy in private clubs. However, as the industry grew, it became accessible to the masses. Today, karaoke can be enjoyed by anyone, in venues ranging from high-end lounges to local shops offering affordable machines. The Vietnamese version of karaoke quickly evolved, embracing the country&#x27;s communal spirit and its love for music. While it began as a form of entertainment, it now serves as a platform for both personal expression and collective bonding. The format is simple: a song, a microphone, and a group of people, each taking turns to belt out their favorite tunes, often accompanied by screens showing lyrics.<br><b>3.</b> A perfect example of this is during Tết, the Vietnamese Lunar New Year, when families come together to celebrate not only the new year but also their shared heritage. Karaoke sessions are a staple of Tết parties, where generations of family members join in to sing favorite songs. It’s not uncommon to see elders singing alongside younger relatives.<br><b>4.</b> Karaoke has blossomed into a highly competitive industry in Vietnam. The rise of commercial karaoke establishments, or KTV lounges, has played a crucial role in shaping the modern nightlife scene, especially in cities like Ho Chi Minh City and Hanoi. <b>These venues</b> offer luxurious-looking interiors, vast selections of songs, and great sound systems. Some high-end lounges even feature themed rooms designed for those who want to enjoy karaoke in a more exclusive setting.<br><b>5.</b> While karaoke is widely enjoyed, it is not without its drawbacks. In cities like Ho Chi Minh City and Hanoi, noise from both karaoke bars and home systems has become a major issue. Whether it’s 12 noon or 12 midnight, complaints continue to rise as people sing at full volume. The problem has prompted local governments to impose regulations on noise levels and operating hours for karaoke venues. There have been efforts to <b>balance</b> the excitement of karaoke with the needs of the community, including campaigns to encourage responsible singing. The implementation of Decree 144/2021/NĐ-CP aimed at reducing the noise from karaoke activities, reflects the government’s efforts to maintain peace while respecting the cultural importance of karaoke.<br>Choose an option (A, B, C, or D) that best answers each question.", "cauHoi": [{"question": "The best title of the passage can be _____.", "choices": ["Karaoke: A Cultural Tradition in Vietnam", "The Rise of Karaoke in Asian", "The Invention of Karaoke in Vietnam", "The Growth of Karaoke Bars in Vietnam"], "correctIndex": 0, "explain": "<b>Chọn đáp án A.</b> Giải thích: Bài viết tổng quát về Karaoke như một truyền thống văn hóa, quá trình phát triển và các vấn đề liên quan tại Việt Nam."}, {"question": "The word &quot;<b>downsides</b>&quot; in paragraph 1 can be replaced by _____.", "choices": ["Benefits", "Drawbacks", "Opportunities", "Inconveniences."], "correctIndex": 1, "explain": "<b>Chọn đáp án B.</b> Giải thích: <b>&quot;Downsides&quot;</b> có nghĩa là mặt hạn chế, tiêu cực, đồng nghĩa với <b>&quot;Drawbacks&quot;</b>."}, {"question": "It can be inferred from paragraph 2 that _____.", "choices": ["Karaoke was invented in Vietnam", "Karaoke initially catered only to the wealthy", "Karaoke bars have always been affordable", "Karaoke is not popular in Ho Chi Minh City"], "correctIndex": 1, "explain": "<b>Chọn đáp án B.</b> Giải thích: Đoạn 2 nêu: &quot;Initially, karaoke was a luxury reserved for the wealthy&quot; (Ban đầu, karaoke là một thứ xa xỉ dành riêng cho người giàu)."}, {"question": "In paragraph 3, which of the following can be inferred?", "choices": ["Karaoke is only popular during the Tết holiday.", "Karaoke is not a significant part of Tết celebrations.", "Younger and older family members often sing together during Tết.", "Elders do not participate in karaoke during Tết."], "correctIndex": 2, "explain": "<b>Chọn đáp án C.</b> Giải thích: Đoạn 3 mô tả cảnh các thế hệ (elders and younger relatives) cùng nhau hát karaoke vào dịp Tết."}, {"question": "It can be seen in paragraphs 1, 2, and 3 that _____.", "choices": ["Karaoke is mainly a modern form of entertainment", "Karaoke is only practiced in large cities", "Karaoke is unpopular during public holidays", "Karaoke is integral to social events and cultural traditions in Vietnam"], "correctIndex": 3, "explain": "<b>Chọn đáp án D. Giải thích: Ba đoạn đầu tập trung vào việc Karaoke là một phần thiết yếu trong giao lưu xã hội và truyền thống (sinh nhật, đám cưới, Tết).</b>"}, {"question": "The phrase &quot;<b>these venues</b>&quot; in paragraph 4 refers to _____.", "choices": ["Cities like Ho Chi Minh City and Hanoi", "Competitive companies", "Luxury restaurants", "KTV lounges."], "correctIndex": 3, "explain": "<b>Chọn đáp án D. Giải thích: &quot;These venues&quot; thay thế cho &quot;commercial karaoke establishments, or KTV lounges&quot; đã nhắc đến ở câu trước đó.</b>"}, {"question": "In paragraph 4, it is NOT mentioned that _____.", "choices": ["Karaoke lounges have luxurious interiors", "Karaoke lounges feature themed rooms", "Karaoke bars offer great sound systems", "Karaoke has excellent customer service."], "correctIndex": 3, "explain": "<b>Chọn đáp án D. Giải thích: Bài đọc nhắc đến nội thất sang trọng, phòng theo chủ đề và hệ thống âm thanh, nhưng không đề cập đến &quot;dịch vụ khách hàng xuất sắc&quot; (excellent customer service).</b>"}, {"question": "In paragraph 5, the author uses the word &quot;<b>balance</b>&quot; to _____.", "choices": ["Show how karaoke venues are trying to satisfy both business owners and the community", "Explain how noise complaints are reducing the popularity of karaoke", "Highlight the need for karaoke to be available all the time", "Describe the struggle between karaoke bars and local governments"], "correctIndex": 0, "explain": "<b>Chọn đáp án A. Giải thích: Từ &quot;balance&quot; (cân bằng) ám chỉ việc chính quyền tìm cách hài hòa giữa nhu cầu giải trí/kinh doanh và sự yên bình của cộng đồng.</b>"}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Nồng độ ion hydroxide <img class=\"anh-de\" src=\"data/anh/l11/d4fd5787c26d4521.png\" alt=\"\" style=\"width:35px;height:22px;vertical-align:middle\">hoặc ion hydrogen <img class=\"anh-de\" src=\"data/anh/l11/b881518876c7c932.png\" alt=\"\" style=\"width:23px;height:20px;vertical-align:middle\">trong dung dịch nước thể hiện tính acid hoặc base của dung dịch đó. Các dung dịch nước có thể có nồng độ ion <img class=\"anh-de\" src=\"data/anh/l11/f4474437e08c8790.png\" alt=\"\" style=\"width:23px;height:20px;vertical-align:middle\">rất cao (môi trường acid mạnh) hoặc rất thấp (môi trường base mạnh). Để biểu thị độ acid hoặc độ base của dung dịch một cách thuận tiện, người ta sử dụng thang đo pH (thang đo logarit). Độ pH của một dung dịch được định nghía bằng công thức: <img class=\"anh-de\" src=\"data/anh/l11/be972ffbbb5d1b8a.png\" alt=\"\" style=\"width:108px;height:29px;vertical-align:middle\">.(<img class=\"anh-de\" src=\"data/anh/l11/80907aec890a6939.png\" alt=\"\" style=\"width:38px;height:29px;vertical-align:middle\">là giá trị nồng độ ion <img class=\"anh-de\" src=\"data/anh/l11/f4474437e08c8790.png\" alt=\"\" style=\"width:23px;height:20px;vertical-align:middle\">, đơn vị: M)<br>Dung dịch có pH nhỏ hơn 7 là acid, pH bằng 7 là trung tính và pH lớn hơn 7 là base.", "cauHoi": [{"question": "Cho các phát biểu sau:<br><b>(a)</b> Giá trị pH của dung dịch môi trường base lớn hơn môi trường acid.<br><b>(b)</b> Để xác định độ lớn giá trị pH cần xác định nồng độ ion <img class=\"anh-de\" src=\"data/anh/l11/df7ad22bf298501a.png\" alt=\"\" style=\"width:23px;height:20px;vertical-align:middle\"><br><b>(c)</b> Dung dịch có giá trị pH càng lớn, tính acid căng mạnh, tính base càng yếu.<br><b>(d)</b> Đất bị chua phù hợp với nhứng loại phân bón có tính acid.<br>Số phát biểu đúng là", "choices": ["1.", "2.", "3.", "4 ."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 103</b><br><b>(a)</b> pH môi trường base &gt; pH môi trường acid → Đúng (vì base có pH &gt; 7, acid &lt; 7)<br><b>(b)</b> Để xác định pH cần xác định nồng độ ion H⁺ → Đúng (vì pH = −log[H⁺])<br><b>(c)</b> pH càng lớn → acid càng mạnh, base càng yếu → Sai <br>→ pH càng lớn thì <b>môi trường càng base</b>, acid càng yếu<br><b>(d)</b> Đất bị chua phù hợp với phân bón có tính acid → Sai <br>→ Đất chua (acid) thì phải dùng <b>phân có tính base</b> để trung hòa<br><b>Chọn đáp án: B. 2</b>"}, {"question": "Môt dung dich có nồng độ ion hydrogen <img class=\"anh-de\" src=\"data/anh/l11/57beba395ae2960d.png\" alt=\"\" style=\"width:98px;height:29px;vertical-align:middle\">. Dựa vào bài đọc, dung dich này có tính chất hóa học nào", "choices": ["Trung tính.", "Acid.", "Base.", "Không kết luận được."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> Cho: <img class=\"anh-de\" src=\"data/anh/l11/7ec8d4b1b4d13383.png\" alt=\"\" style=\"width:100px;height:29px;vertical-align:middle\"><img class=\"anh-de\" src=\"data/anh/l11/470547a5a56d4275.png\" alt=\"\" style=\"width:154px;height:29px;vertical-align:middle\">→ pH &lt; 7 ⇒ môi trường acid<br><b>Đáp án: B. Acid</b>"}, {"question": "Chất chỉ thị phenolphtalein là chất không màu trong môi trường acid ( pH từ 0 đến 8.2) và có màu hồng trong môi trường base (pH từ 10.0 đến 12.0). Khi thêm phenolphtalein vào một dung dịch có nồng độ ion <img class=\"anh-de\" src=\"data/anh/l11/f4474437e08c8790.png\" alt=\"\" style=\"width:23px;height:20px;vertical-align:middle\">bằng <img class=\"anh-de\" src=\"data/anh/l11/2d1c64ce9d54f044.png\" alt=\"\" style=\"width:33px;height:22px;vertical-align:middle\">, hiện tượng nào sẽ xảy ra?", "choices": ["Dung dịch chuyển sang màu hồng.", "Dung dịch chuyển từ không màu sang màu tím.", "Dung dịch chuyển sang màu xanh.", "Dung dịch không thay đổi màu."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <img class=\"anh-de\" src=\"data/anh/l11/d36ec8131968be01.png\" alt=\"\" style=\"width:160px;height:29px;vertical-align:middle\"> → Đây là môi trường base mạnh<br><b>Chọn đáp án: A.</b> Dung dịch chuyển sang màu hồng"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Năng lượng liên kết riêng của một hạt nhân được xác định bằng năng lượng liên kết toàn phần chia cho số nuclon (tổng số proton và neutron) trong hạt nhân đó, thường đo bằng đơn vị MeV/nuclon. Đại lượng này phản ánh mức độ bền vững của hạt nhân: giá trị càng lớn thì hạt nhân càng ổn định.<br>Kết quả khảo sát thực nghiệm cho thấy năng lượng liên kết riêng phụ thuộc vào số khối A theo một quy luật đặc trưng. Đối với các hạt nhân nhẹ (A nhỏ), giá trị này tăng nhanh theo số khối. Trong khoảng A từ vài đơn vị đến khoảng 50–60, năng lượng liên kết riêng đạt giá trị lớn nhất, xấp xỉ 8,7–8,8 MeV/nuclon. Khi số khối tiếp tục tăng, đại lượng này giảm dần đối với các hạt nhân nặng.<br>Xu hướng trên cho thấy các hạt nhân có số khối trung bình có độ bền cao hơn so với các hạt nhân quá nhẹ hoặc quá nặng. Điều này liên quan đến sự cân bằng giữa lực hút hạt nhân mạnh và lực đẩy tĩnh điện giữa các proton trong hạt nhân.<br>Từ quy luật biến thiên của năng lượng liên kết riêng, có thể giải thích sự tồn tại của hai dạng phản ứng hạt nhân phổ biến. Ở một phía, các hạt nhân nhẹ có xu hướng kết hợp tạo thành hạt nhân nặng hơn. Ở phía còn lại, các hạt nhân rất nặng có xu hướng phân tách thành các hạt nhân có khối lượng trung bình. Trong cả hai trường hợp, sự biến đổi đều hướng tới trạng thái có độ bền cao hơn.", "cauHoi": [{"question": "Xét các phát biểu sau:<br>(1) Năng lượng liên kết càng lớn thì hạt nhân càng bền vững.<br>(2) Với mọi hạt nhân số khối càng tăng, thì năng lượng liên kết riêng càng giảm dần<br>(3) Hạt nhân có số khối trung bình thường có độ bền lớn hơn hạt nhân rất nhẹ và rất nặng. (4) Đối với hạt nhân nhẹ, năng lượng liên kết riêng tăng khi số khối tăng.<br>(5) Đối với hạt nhân nặng, năng lượng liên kết riêng giảm khi số khối tăng.<br>(6) Mọi hạt nhân đều có năng lượng liên kết riêng như nhau.<br>Số phát biểu đúng là:", "choices": ["2", "3", "4", "5"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn: Chọn đáp án B. 3 ý đúng.</u></b><br><b>(1) Sai:</b> Hạt nhân nào có năng lượng liên kết <b>riêng</b> lớn hơn thì <b>bền vững</b> hơn.<br><b>(2) Sai: Vì “ </b>Đối với các hạt nhân nhẹ (A nhỏ), giá trị này tăng nhanh theo số khối. Trong khoảng A từ vài đơn vị đến khoảng 50–60, năng lượng liên kết riêng đạt giá trị lớn nhất, xấp xỉ 8,7–8,8 MeV/nuclon. Khi số khối tiếp tục tăng, đại lượng này giảm dần đối với các hạt nhân nặng.”<br><b>(3) Đúng:</b> Các hạt nhân có số khối trong khoảng 50 &lt; A &lt; 95 (vùng trung bình) có năng lượng liên kết riêng lớn nhất (khoảng <img class=\"anh-de\" src=\"data/anh/l11/15377f64648236f0.png\" alt=\"\" style=\"width:119px;height:22px;vertical-align:middle\">), do đó chúng bền vững nhất.<br><b>(4) Đúng:</b> Theo đường cong năng lượng liên kết, ở vùng hạt nhân nhẹ, khi số khối A tăng thì năng lượng liên kết riêng có xu hướng tăng lên.<br><b>(5) Đúng:</b> Ở vùng hạt nhân nặng (<img class=\"anh-de\" src=\"data/anh/l11/43fb34692ce4292d.png\" alt=\"\" style=\"width:53px;height:18px;vertical-align:middle\">), năng lượng liên kết riêng giảm dần khi A tăng.<br><b>(6) Sai:</b> Mỗi hạt nhân có một cấu trúc và độ hụt khối khác nhau, do đó năng lượng liên kết riêng của chúng là khác nhau."}, {"question": "<b>Dựa vào đồ thị năng lượng liên kết riêng theo số khỡi, hãy sắp xếp các hạt nhân sau theo thứ tự độ bền vững tăng dần: </b>", "choices": ["<img class=\"anh-de\" src=\"data/anh/l11/8d60ed6bb516b7d0.png\" alt=\"\" style=\"width:174px;height:22px;vertical-align:middle\">", "<img class=\"anh-de\" src=\"data/anh/l11/b7a1126e1bc3cdde.png\" alt=\"\" style=\"width:179px;height:22px;vertical-align:middle\">", "<img class=\"anh-de\" src=\"data/anh/l11/a8d61fe785efc865.png\" alt=\"\" style=\"width:179px;height:22px;vertical-align:middle\">", "<img class=\"anh-de\" src=\"data/anh/l11/5770c43a4c924b4f.png\" alt=\"\" style=\"width:174px;height:22px;vertical-align:middle\">"], "correctIndex": 0, "explain": "<b><u>Hướng dẫn: Chọn đáp án A</u></b><img class=\"anh-de\" src=\"data/anh/l11/df5050e617cf20d1.png\" alt=\"\" style=\"width:33px;height:25px;vertical-align:middle\"><b> </b>gần cực đại → bền nhất<br>Các hạt nhân nặng hơn: năng lượng liên kết riêng giảm dần<b> </b><img class=\"anh-de\" src=\"data/anh/l11/41a9885f51f1b9ca.png\" alt=\"\" style=\"width:180px;height:22px;vertical-align:middle\">"}, {"question": "Một hạt nhân <img class=\"anh-de\" src=\"data/anh/l11/d211d513d2613cfe.png\" alt=\"\" style=\"width:18px;height:18px;vertical-align:middle\"> có năng lượng liên kết toàn phần là <img class=\"anh-de\" src=\"data/anh/l11/6062d9450588a333.png\" alt=\"\" style=\"width:74px;height:22px;vertical-align:middle\"> và năng lượng liê̂n kết riêng là <img class=\"anh-de\" src=\"data/anh/l11/a3340dbd5f067d07.png\" alt=\"\" style=\"width:119px;height:22px;vertical-align:middle\">Dựa vào đồ thị năng lượng liên kết riêng theo số khối, hãy dự đoán hạt nhân X thuộc nguyên tố nào sau đây?", "choices": ["C (Cacbon)", "Fe (Sắt)", "U (Uranium)", "He (Heli)"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn</u></b> Tính số khối: <img class=\"anh-de\" src=\"data/anh/l11/12d79b39b4c555dd.png\" alt=\"\" style=\"width:103px;height:44px;vertical-align:middle\">\\(\\Rightarrow\\) nguyên tố X là sắt (Fe)<b><u> Chọn đáp án B</u></b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Sữa chua là một sản phẩm được làm từ sữa, giàu chất dinh dưỡng. Trong sữa chua có các chất như: protein (chất đạm), lipid (chất béo) có sẵn trong sữa đã được tiêu hóa một phần, rút ngắn thời gian hấp thu trong hệ thống tiêu hóa. Đường lactose đã được lên men dễ hấp thu, làm giảm lượng đường tồn đọng lại ở hệ tiêu hóa tránh được tiêu chảy, giúp cho cơ thể hấp thu calcium và một số khoáng chất khác dễ dàng hơn.<br>Các vi khuẩn này thường hoạt động hiệu quả trong khoảng nhiệt độ trung bình, phổ biến vào khoảng 30–45°C, và có thể bị ức chế mạnh khi nhiệt độ tăng cao; nhiều nghiên cứu cho thấy hoạt tính của chúng giảm rõ rệt khi vượt quá 50°C. Ngoài ra, sự thay đổi nhiệt độ cũng ảnh hưởng đến tốc độ tạo axit, từ đó làm thay đổi độ chua và cấu trúc của sản phẩm.<br>Vi khuẩn lactic là nhóm vi sinh vật có khả năng chuyển hóa đường lactose trong sữa thành axit lactic, góp phần tạo nên hương vị đặc trưng của sữa chua. Mang một hàm lượng dinh dưỡng khá cao, sữa chua rất tốt cho mọi người, đặc biệt là phụ nữ và trẻ em. Đối với trẻ nhỏ, sữa chua ngăn ngừa một số bệnh đường ruột, bổ sung thêm acid cho dịch dạ dày (ở trẻ nhỏ nồng độ acid trong dạ dày chưa đạt được tiêu chuẩn như ở người lớn) giúp cho việc tiêu hóa thức ăn được dễ dàng hơn. Không những vậy, một số loại sữa chua còn thêm DHA (chất béo không no chuỗi dài) có tác dụng giúp sáng mắt và tăng chỉ số phát triển trí tuệ.", "cauHoi": [{"question": "Vi sinh vật cần có trong quá trình sản xuất sữa chua là", "choices": ["nấm men.", "vi khuẩn lactic.", "vi khuẩn acetic.", "vi khuẩn nitrate hoá."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Đáp án: B. vi khuẩn lactic.</b><br><b>Giải thích: </b>Trong quá trình làm sữa chua, <b>vi khuẩn lactic</b> sẽ lên men đường lactose → tạo <b>acid lactic</b>, làm sữa có vị chua và hỗ trợ đông tụ."}, {"question": "Sữa chua từ trạng thái lỏng trở thành sệt là vì", "choices": ["protein của sữa kết tủa.", "amino acid của sữa kết tủa.", "cacbohydrate của sữa kết tủa.", "lipid của sữa kết tủa."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b>Đáp án: A. protein của sữa kết tủa.</b><br><b>Giải thích: </b>Acid lactic làm giảm pH → <b>protein (casein) trong sữa bị kết tủa</b>, tạo cấu trúc <b>sệt, đặc</b> của sữa chua."}, {"question": "Khi làm sữa chua, bạn A thực hiện các bước như sau<br>Bước 1: pha sữa ngọt vừa uống bằng nước ấm \\(40{^\\circ}C\\).<br>Bước 2: Cho 1 hộp sữa chua vào rồi trộn đều.<br>Bước 3: Đun nóng ở nhiệt độ 60\\({^\\circ}\\)C trong 10 phút.<br>Bước 4: Để vào tủ lạnh trong 4 – 6h<br>Sau 4 – 6h, A thấy hỗn hợp nhìn giống sữa chua nhưng ăn không có vị chua, có nhiều đá.<br>Theo em A đã làm sai ở bước nào?", "choices": ["Bước 1.", "Bước 2.", "Bước 3.", "Bước 4."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> Đáp án: <b>C. Bước 3.</b><br><b>Giải thích:</b><br>Vi khuẩn lactic hoạt động tốt khoảng <b>40–45°C</b><br>Ở <b>60°C</b>, vi khuẩn sẽ <b>bị chết</b> → không lên men → <b>không tạo vị chua</b><br>Sau đó đem lạnh → bị <b>đông đá</b>, nên thấy “nhiều đá”<br>Sai ở <b>bước đun nóng 60°C sau khi đã cho men</b>."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Dân số trung bình của Việt Nam năm 2023 đạt 100,3 triệu người, trong đó tỷ lệ dân số nam và nữ khá cân bằng (nam giới chiếm <img class=\"anh-de\" src=\"data/anh/l11/81253377617b9a5f.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\">, nữ giới <img class=\"anh-de\" src=\"data/anh/l11/88cb1982a219db73.png\" alt=\"\" style=\"width:45px;height:22px;vertical-align:middle\"> ). Dân số trung bình khu vực thành thị là 38,2 triệu người, chiếm <img class=\"anh-de\" src=\"data/anh/l11/56e0bf4274f53eb4.png\" alt=\"\" style=\"width:45px;height:22px;vertical-align:middle\">; khu vực nông thôn là 62,1 triệu người, chiếm <img class=\"anh-de\" src=\"data/anh/l11/fb648a84f5646c06.png\" alt=\"\" style=\"width:47px;height:22px;vertical-align:middle\">.<br>Trong năm 2023 này, tỉ suất sinh thô đạt khoảng 15‰, tỉ suất tử thô khoảng 6‰, nên mức tăng dân số do gia tăng tự nhiên vẫn duy trì ở mức dương.<br>Bên cạnh đó, quá trình đô thị hóa và phát triển kinh tế đã làm gia tăng các luồng di cư giữa các vùng, đặc biệt là từ nông thôn ra thành thị, góp phần tạo nên gia tăng cơ học của dân số.<br>Nhìn chung, quy mô dân số Việt Nam tiếp tục tăng, tuy nhiên tốc độ tăng có xu hướng giảm nhẹ trong những năm gần đây (năm 2022 là 0,98%, năm 2023 là 0,84%), phản ánh sự tác động đồng thời của cả yếu tố sinh – tử và di cư.<br>Việt Nam là quốc gia đông dân thứ ba trong khu vực Đông Nam Á (sau In-đô-nê-xi-a và Phi-lip-pin) và đứng thứ 15 trên thế giới. Do mức sinh có xu hướng giảm nhẹ nên tốc độ tăng dân số giảm dẩn trong những năm gẩn đây và dự báo tiếp tục giảm trong những năm tiếp theo (tốc độ tăng dân số trung bình năm 2022 là <img class=\"anh-de\" src=\"data/anh/l11/f7b6ac8a1e593acc.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\">, năm 2023 là <img class=\"anh-de\" src=\"data/anh/l11/6d8a50ea94b726cb.png\" alt=\"\" style=\"width:47px;height:22px;vertical-align:middle\"> ).<br><i>(Nguồn: Tổng cục thống kê)</i>", "cauHoi": [{"question": "Theo số liệu từ đoạn thông tin và kiến thức đã học, cho biết mật độ dân số của Việt Nam năm 2023 là", "choices": ["381 người/<img class=\"anh-de\" src=\"data/anh/l11/bc6c12b06d9eed45.png\" alt=\"\" style=\"width:31px;height:20px;vertical-align:middle\">.", "329 người <img class=\"anh-de\" src=\"data/anh/l11/df2c0868e61ec93a.png\" alt=\"\" style=\"width:38px;height:22px;vertical-align:middle\">.", "382 người <img class=\"anh-de\" src=\"data/anh/l11/1190e836fd3351a8.png\" alt=\"\" style=\"width:38px;height:22px;vertical-align:middle\">.", "303 người <img class=\"anh-de\" src=\"data/anh/l11/1190e836fd3351a8.png\" alt=\"\" style=\"width:38px;height:22px;vertical-align:middle\">."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b><br>\\[\\text{~Mật độ dân số~} = \\frac{\\text{~Dân số~}}{\\text{~Diện tích~}}\\]<br>Dân số: 100,3 triệu người<br>Diện tích Việt Nam \\(\\approx 331.000{\\text{ }km}^{2}\\)<br>\\[\\frac{100,3 \\times 10^{6}}{331.000} \\approx 303người/{km}^{2}\\]<br><b>Chọn đáp án D</b>"}, {"question": "Theo bài đọc, tỉ lệ gia tăng dân số được tính bằng", "choices": ["tỉ lệ gia tăng dân số tự nhiên + tỉ lệ gia tăng dân số cơ học.", "tỉ lệ gia tăng dân số tự nhiên - tỉ lệ gia tăng dân số cơ học.", "tỉ lệ sinh thô - tỉ lệ tử thô.", "tỉ lệ sinh thô/ tỉ lệ tử thô"], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b><br>Đoạn 2 có <b>2 ý sau</b>:<br>“gia tăng tự nhiên” (liên quan sinh – tử)<br>“gia tăng cơ học” (liên quan di cư)<br>Sau đó bài nói: “phản ánh sự tác động <b>đồng thời của cả yếu tố sinh – tử và di cư</b>”<br>Từ “đồng thời” “và” chính là <b>tín hiệu cho biết: </b>tỉ lệ gia tăng dân số tự nhiên + tỉ lệ gia tăng dân số cơ học<b> </b>"}, {"question": "Việt Nam là quốc gia có dân số đông <b>không</b> thể hiện qua số liệu nào sau đây?", "choices": ["Dân số trung bình của Việt Nam năm 2023 đạt 100,3 triệu người.", "Việt Nam là quốc gia đông dân thứ ba trong khu vực Đông Nam Á.", "Dân số thành thị chiếm 38,1% tổng số dân cả nước.", "Việt Nam là quốc gia đông dân thứ 15 trên thế giới."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b><br>A. Chỉ nói tổng dân số → chưa phản ánh “đông” hay “thưa” theo mật độ<br>B. Thứ hạng trong khu vực → thể hiện đông<br>C. Tỉ lệ thành thị → gián tiếp phản ánh phân bố<br>D. Thứ hạng thế giới → thể hiện đông<br><b>Chọn đáp án A</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117 </b><br>Giai đoạn 1995 - 2013 chứng kiến những bước phát triển vượt bậc và toàn diện trong quan hệ Việt Nam - Hoa Kỳ. Tuyên bố về Đối tác toàn diện Việt Nam - Hoa Kỳ được ký kết vào năm 2013 đã tạo lập khuôn khổ quan hệ cho hai nước, khẳng định xu thế phát triển tất yếu của quan hệ Việt Nam - Hoa Kỳ, đồng thời tạo nền tảng vững chắc cho sự phát triển của quan hệ song phương những năm tiếp theo. Hai nước cam kết hợp tác toàn diện trên chín lĩnh vực chủ chốt, bao gồm: chính trị - ngoại giao, thương mại - kinh tế, khoa học - công nghệ, giáo dục - đào tạo, môi trường, y tế, giải quyết hậu quả chiến tranh, quốc phòng - an ninh, bảo vệ và thúc đẩy quyền con người, văn hóa - thể thao - du lịch. Hai bên nhấn mạnh các nguyên tắc trong quan hệ đối tác toàn diện trên cơ sở tôn trọng luật pháp quốc tế và Hiến chương Liên hợp quốc, cũng như độc lập, chủ quyền, toàn vẹn lãnh thổ và thể chế chính trị của nhau. Đây là lần đầu tiên Hoa Kỳ khẳng định tôn trọng thể chế chính trị của Việt Nam.<br>(Nguồn: https://www.tapchicongsan.org.vn/)", "cauHoi": [{"question": "Năm 2013, là mốc quan trọng đánh dấu mối quan hệ ngoại giao của Việt Nam – Hoa Kì là", "choices": ["đối tác chiến lược.", "đối tác chiến lược lĩnh vực.", "đối tác toàn diện.", "đối tác chiến lược toàn diện."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b><br><b>Đáp án: C</b><br><b>Giải thích:</b> Đoạn văn nêu rõ: “Tuyên bố về Đối tác toàn diện Việt Nam - Hoa Kỳ được ký kết vào năm 2013” ⇒ mốc 2013 là đối tác toàn diện, chưa phải chiến lược hay chiến lược toàn diện."}, {"question": "Nền tảng vững chắc cho sự phát triển quan hệ song phương Việt Nam – Hoa Kì từ năm 2013 là", "choices": ["Tuyên bố về Đối tác toàn diện Việt Nam - Hoa Kỳ.", "luật pháp quốc tế.", "Hiến chương Liên hợp quốc.", "sự tôn trọng các quyền dân tộc cơ bản của mỗi quốc gia."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b><br><b>Đáp án: A</b><br>Giải thích: Đoạn văn ghi rõ: “Tuyên bố … đã … tạo nền tảng vững chắc cho sự phát triển của quan hệ song phương những năm tiếp theo” <b>⇒ chọn A.</b><br>Các ý B, C, D chỉ là nguyên tắc, không phải “nền tảng trực tiếp” được nhắc đến."}, {"question": "Giai đoạn 1995 – 2013, quan hệ Việt Nam – Hoa Kì", "choices": ["từ bao vây cấm vận đến đối tác chiến lược.", "từ quan hệ đặc biệt đến đối tác toàn diện.", "từ đối tác chiến lược lĩnh vực đến quan hệ đặc biệt.", "từ bình thường hóa đến đối tác toàn diện."], "correctIndex": 3, "explain": "<b>Đáp án: D</b><br>Giải thích:<br>Năm 1995: Việt Nam – Hoa Kỳ bình thường hóa quan hệ.<br>Năm 2013: nâng lên đối tác toàn diện.<br>⇒ Quá trình là: bình thường hóa → đối tác toàn diện."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Trong quá trình phát triển kinh tế - xã hội, Đảng và Nhà nước ta rất chú trọng vào con người, nhất là những người nghèo, được dư luận quốc tế đánh giá là một trong những quốc gia điển hình trong việc thực hiện Mục tiêu Thiên niên kỷ về xóa đói, giảm nghèo. Theo chuẩn quốc gia, tỷ lệ hộ nghèo đã giảm từ 30% năm 1992 xuống còn 5,8% năm 2016; tính theo chuẩn nghèo tiếp cận đa chiều giảm từ 14,2% năm 2010 xuống còn 6,8% năm 2018, riêng các huyện nghèo giảm 4%. Đến nay, hầu hết các đối tượng chính sách xã hội, trẻ em dưới 6 tuổi, người nghèo, đồng bào dân tộc thiểu số ở các vùng khó khăn đã có bảo hiểm y tế; cấp thẻ bảo hiểm y tế cho trên 34,3 triệu người, hỗ trợ mua thẻ bảo hiểm y tế cho trên 15,1 triệu người. Người dân thụ hưởng những thành quả của tăng trưởng kinh tế, từ đó vươn lên thoát nghèo, cải thiện đời sống vật chất và tinh thần.", "cauHoi": [{"question": "Trong thông tin trên, nội dung nào dưới đây thể hiện trách nhiệm của công dân trong việc chính sách an sinh xã hội của nhà nước?", "choices": ["Tự hào với thế giới vì đã thoát nghèo.", "Được cấp phát thẻ bảo hiểm miễn phí.", "Được thụ hưởng thành quả tăng trưởng.", "Tích cực chủ động vươn lên thoát nghèo."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b> A, B, C → đều là <b>quyền lợi / kết quả được hưởng</b><br><b>Chọn đáp án: D. Tích cực chủ động vươn lên thoát nghèo.</b><br>Vì công dân không chỉ thụ hưởng mà còn phải <b>tự nỗ lực cải thiện cuộc sống</b>, góp phần giảm nghèo bền vững."}, {"question": "Từ những số liệu trong thông tin trên, nhận định nào dưới đây <b>không</b> phải là nội dung của phát triển bền vững?", "choices": ["Đảng và Nhà nước ta rất chú trọng vào con người, nhất là những người nghèo.", "Tỷ lệ hộ nghèo đa chiều đã giảm từ 30% năm 1992 xuống còn 5,8% năm 2016.", "Các đối tượng chính sách xã hội đã được cấp hoặc hỗ trợ mua bảo hiểm y tế.", "Quốc tế ghi nhận và xếp hạng các quốc gia thực hiện Mục tiêu Thiên niên."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b><br>Câu A → đúng (lấy con người làm trung tâm)<br>Câu B → đúng (giảm nghèo là tiêu chí bền vững)<br>Câu C → đúng (an sinh xã hội, y tế)<br><b><u>Chọn đáp án: D</u></b> <b>chỉ là sự ghi nhận quốc tế</b>, không phải nội dung phát triển."}, {"question": "Trong thông tin trên, nội dung nào dưới đây thể hiện kết quả của việc thực hiện các chính sách an sinh xã hội của Đảng và Nhà nước?", "choices": ["Chú trọng xóa đói giảm nghèo.", "Cấp thẻ bảo hiểm cho trẻ dưới 6 tuổi.", "Tỷ lệ hộ nghèo đa chiều đã giảm.", "Hỗ trợ người dân mua bảo hiểm."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> A → chủ trương<br>B, D → biện pháp (cách làm)<br><b>Chọn đáp án C → kết quả cụ thể (giảm tỷ lệ nghèo)</b>"}], "khongXaoTron": true}]};
